import sys; sys.path.insert(0, "code")
import torch, torch.nn as nn
torch.backends.quantized.engine = "qnnpack"
class M(nn.Module):
    def __init__(self):
        super().__init__()
        self.lin = nn.Linear(16, 8)
    def forward(self, x):
        return self.lin(x)
m = M()
q = torch.quantization.quantize_dynamic(m, {nn.Linear}, dtype=torch.qint8)
print("type:", type(q.lin).__name__)
print("weight dtype:", q.lin.weight.dtype)
print("has qweight:", hasattr(q.lin, 'qweight'))
# Check the actual module
for name, mod in q.named_modules():
    print(name, type(mod).__name__, end=" ")
    if hasattr(mod, 'weight'):
        print("w_dtype:", mod.weight.dtype, end=" ")
    if hasattr(mod, 'qweight'):
        print("qweight:", mod.qweight.dtype, end=" ")
    print()
EOF

