def test_quantize_dynamic_conv2d_produces_qnnpack():
    """quantize_dynamic({nn.Conv2d}) with qnnpack engine produces a Conv2d
    whose _packed_params carries a qint8 quantized weight."""
    P.set_qnnpack_engine()

    class M(nn.Module):
        def __init__(self):
            super().__init__()
            self.conv = nn.Conv2d(1, 4, 3, padding=1)
        def forward(self, x):
            return self.conv(x)

    m = M()
    q = torch.quantization.quantize_dynamic(m, {nn.Conv2d}, dtype=torch.qint8)
    pp = q.conv._packed_params
    sd = pp.state_dict()
    assert "dtype" in sd, "no dtype in packed_params state_dict"
    assert sd["dtype"] == torch.qint8, f"packed dtype {sd['dtype']} != qint8"

