def _is_qnnpack_quantized_linear(mod: nn.Module) -> bool:
    """True if `mod` is a qnnpack dynamic-quantized Linear produced by
    quantize_dynamic. The public module class is nn.Linear, but it carries
    a `_packed_params` child (LinearPackedParams) that holds the qint8
    weight. We detect it by the presence of `_packed_params`."""
    if not isinstance(mod, nn.Linear):
        return False
    return hasattr(mod, "_packed_params")

